import re,base64
from pathlib import Path
p=Path('whatsapp-score.html')
h=p.read_text(encoding='utf-8')
logo='data:image/webp;base64,'
h=re.sub(r'(<img[^>]+alt="STall logo"[^>]+src=")[^"]+("[^>]*>)',lambda m:m.group(1)+logo+m.group(2),h)
footer='''<footer class="footer"><div class="footer-brand"><img class="logo" alt="STall logo" src="'''+logo+'''"><div class="footer-slogan">Salons Grow Stronger Together</div></div><div class="footer-right"><div class="tag">DISCOVER <b>•</b> CONNECT <b>•</b> GROW</div><small>A digital edge for every salon</small></div></footer>'''
h=re.sub(r'<footer class="footer">.*?</footer>',footer,h,flags=re.S)
h=h.replace('</style></head>', '''.footer{margin:20px -18px -55px;padding:34px 7%;background:#111216;color:#fff;display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(217,173,82,.45);position:relative;overflow:hidden}.footer:before{content:"";position:absolute;top:-2px;left:0;right:0;height:3px;background:linear-gradient(90deg,transparent,var(--gold),transparent);opacity:.85}.footer-brand{display:flex;align-items:center;gap:18px}.footer .logo{width:82px;height:69px;object-fit:contain;background:transparent}.footer-slogan{font-size:22px;font-weight:800;letter-spacing:-.02em;color:#f4d276}.footer-right{text-align:right}.footer-right .tag{font-size:10px;letter-spacing:.25em;font-weight:800}.footer-right .tag b{color:var(--gold);margin:0 8px}.footer-right small{display:block;color:#aaa;margin-top:8px;letter-spacing:.08em}@media(max-width:800px){.footer{display:block;text-align:center;padding:30px 20px}.footer-brand{justify-content:center;gap:12px}.footer .logo{width:74px;height:62px}.footer-slogan{font-size:18px}.footer-right{text-align:center;margin-top:18px}} </style></head>''')
p.write_text(h,encoding='utf-8')
print('footer polished')